// AES_GCM_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module AES_GCM_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_key256,
  input logic  c_decrypt,
  input logic  c_key_sel,
  input logic [3:0] c_tag_len,
  input logic [255:0] c_key,
  input logic [95:0] c_iv,
  input logic [127:0] c_tag_in,
  input logic  c_start,
  input logic  c_clr,
  input logic [127:0] c_in_data,
  input logic [4:0] c_in_bytes,
  input logic  c_in_aad,
  input logic  c_in_last,
  input logic [127:0] c_out_data,
  input logic [4:0] c_out_bytes,
  input logic  c_out_last,
  input logic [127:0] c_tag,
  input logic  c_busy,
  input logic  c_tag_ok,
  input logic [2:0] c_err_code,
  input logic  c_in_valid,
  input logic  c_in_ready,
  input logic  c_out_valid,
  input logic  c_out_ready,
  input logic  c_done,
  input logic  c_err
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 37;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:36];          // model of every stored word
  logic [4:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_IN;          // full / valid pulse / available
  logic m_state_OUT;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_done) m_set[0] = 1'b1;
    if (c_err) m_set[1] = 1'b1;
    if (m_state_IN && c_in_ready) m_set[2] = 1'b1;
    if (m_wr && m_map && (m_idx == 22 || m_idx == 23 || m_idx == 24 || m_idx == 25 || m_idx == 26) && m_state_IN) m_set[3] = 1'b1;
    if (c_out_valid && !m_state_OUT) m_set[4] = 1'b1;
    if (c_out_valid && m_state_OUT && (m_rd && m_map && m_idx == 31)) m_set[4] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_w[25] <= 32'h0;
      m_w[26] <= 32'h0;
      m_w[27] <= 32'h0;
      m_w[28] <= 32'h0;
      m_w[29] <= 32'h0;
      m_w[30] <= 32'h0;
      m_w[31] <= 32'h0;
      m_w[32] <= 32'h0;
      m_w[33] <= 32'h0;
      m_w[34] <= 32'h0;
      m_w[35] <= 32'h0;
      m_w[36] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_IN <= 0;
      m_state_OUT <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7F;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 15) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 16) m_w[16] <= ((m_w[16] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 17) m_w[17] <= ((m_w[17] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 18) m_w[18] <= ((m_w[18] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 19) m_w[19] <= ((m_w[19] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 20) m_w[20] <= ((m_w[20] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 21) ? PWDATA & m_be & 32'h3 : 0;
      if (m_wr && m_map && m_idx == 22 && !m_state_IN) m_w[22] <= ((m_w[22] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 23 && !m_state_IN) m_w[23] <= ((m_w[23] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 24 && !m_state_IN) m_w[24] <= ((m_w[24] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 25 && !m_state_IN) m_w[25] <= ((m_w[25] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 26 && !m_state_IN) m_w[26] <= ((m_w[26] & ~m_be) | (PWDATA & m_be)) & 32'h7F;
      if (m_wr && m_map && m_idx == 26 && !m_state_IN) m_state_IN <= 1;
      if (m_state_IN && c_in_ready) m_state_IN <= 0;
      if (c_out_valid && (!m_state_OUT || (m_rd && m_map && m_idx == 31))) begin
        m_w[27] <= (32'(c_out_data[31:0]) << 0);
        m_w[28] <= (32'(c_out_data[63:32]) << 0);
        m_w[29] <= (32'(c_out_data[95:64]) << 0);
        m_w[30] <= (32'(c_out_data[127:96]) << 0);
        m_w[31] <= (32'(c_out_bytes[4:0]) << 0) | (32'(c_out_last) << 5);
        m_state_OUT <= 1;
      end else if ((m_rd && m_map && m_idx == 31)) m_state_OUT <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h41470100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_OUT, m_state_IN});
      4: return m_w[4];
      5: return m_w[5];
      6: return 0;
      7: return 0;
      8: return 0;
      9: return 0;
      10: return 0;
      11: return 0;
      12: return 0;
      13: return 0;
      14: return m_w[14];
      15: return m_w[15];
      16: return m_w[16];
      17: return m_w[17];
      18: return m_w[18];
      19: return m_w[19];
      20: return m_w[20];
      21: return 0;
      22: return m_w[22];
      23: return m_w[23];
      24: return m_w[24];
      25: return m_w[25];
      26: return m_w[26];
      27: return m_w[27];
      28: return m_w[28];
      29: return m_w[29];
      30: return m_w[30];
      31: return m_w[31];
      32: return (32'(c_tag[31:0]) << 0);
      33: return (32'(c_tag[63:32]) << 0);
      34: return (32'(c_tag[95:64]) << 0);
      35: return (32'(c_tag[127:96]) << 0);
      36: return (32'(c_busy) << 0) | (32'(c_tag_ok) << 1) | (32'(c_err_code) << 2);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][4:0] & m_w[2][4:0]))
  `SVA_INV(a_core_key256, c_key256 == m_w[5][0:0])
  `SVA_INV(a_core_decrypt, c_decrypt == m_w[5][1:1])
  `SVA_INV(a_core_key_sel, c_key_sel == m_w[5][2:2])
  `SVA_INV(a_core_tag_len, c_tag_len == m_w[5][6:3])
  `SVA_INV(a_core_key_31_0, c_key[31:0] == m_w[6][31:0])
  `SVA_INV(a_core_key_63_32, c_key[63:32] == m_w[7][31:0])
  `SVA_INV(a_core_key_95_64, c_key[95:64] == m_w[8][31:0])
  `SVA_INV(a_core_key_127_96, c_key[127:96] == m_w[9][31:0])
  `SVA_INV(a_core_key_159_128, c_key[159:128] == m_w[10][31:0])
  `SVA_INV(a_core_key_191_160, c_key[191:160] == m_w[11][31:0])
  `SVA_INV(a_core_key_223_192, c_key[223:192] == m_w[12][31:0])
  `SVA_INV(a_core_key_255_224, c_key[255:224] == m_w[13][31:0])
  `SVA_INV(a_core_iv_31_0, c_iv[31:0] == m_w[14][31:0])
  `SVA_INV(a_core_iv_63_32, c_iv[63:32] == m_w[15][31:0])
  `SVA_INV(a_core_iv_95_64, c_iv[95:64] == m_w[16][31:0])
  `SVA_INV(a_core_tag_in_31_0, c_tag_in[31:0] == m_w[17][31:0])
  `SVA_INV(a_core_tag_in_63_32, c_tag_in[63:32] == m_w[18][31:0])
  `SVA_INV(a_core_tag_in_95_64, c_tag_in[95:64] == m_w[19][31:0])
  `SVA_INV(a_core_tag_in_127_96, c_tag_in[127:96] == m_w[20][31:0])
  `SVA_INV(a_core_start, c_start == m_pulse_CMD[0])
  `SVA_INV(a_core_clr, c_clr == m_pulse_CMD[1])
  `SVA_INV(a_core_in_data_31_0, c_in_data[31:0] == m_w[22][31:0])
  `SVA_INV(a_core_in_data_63_32, c_in_data[63:32] == m_w[23][31:0])
  `SVA_INV(a_core_in_data_95_64, c_in_data[95:64] == m_w[24][31:0])
  `SVA_INV(a_core_in_data_127_96, c_in_data[127:96] == m_w[25][31:0])
  `SVA_INV(a_core_in_bytes, c_in_bytes == m_w[26][4:0])
  `SVA_INV(a_core_in_aad, c_in_aad == m_w[26][5:5])
  `SVA_INV(a_core_in_last, c_in_last == m_w[26][6:6])
  `SVA_INV(a_core_in_valid, c_in_valid == m_state_IN)
  `SVA_INV(a_core_out_ready, c_out_ready == (!m_state_OUT || (m_rd && m_map && m_idx == 31)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_key256 == 1'h0 && c_decrypt == 1'h0 && c_key_sel == 1'h0 && c_tag_len == 4'h0 && c_key[31:0] == 32'h0 && c_key[63:32] == 32'h0 && c_key[95:64] == 32'h0 && c_key[127:96] == 32'h0 && c_key[159:128] == 32'h0 && c_key[191:160] == 32'h0 && c_key[223:192] == 32'h0 && c_key[255:224] == 32'h0 && c_iv[31:0] == 32'h0 && c_iv[63:32] == 32'h0 && c_iv[95:64] == 32'h0 && c_tag_in[31:0] == 32'h0 && c_tag_in[63:32] == 32'h0 && c_tag_in[95:64] == 32'h0 && c_tag_in[127:96] == 32'h0 && c_start == 1'h0 && c_clr == 1'h0 && c_in_data[31:0] == 32'h0 && c_in_data[63:32] == 32'h0 && c_in_data[95:64] == 32'h0 && c_in_data[127:96] == 32'h0 && c_in_bytes == 5'h0 && c_in_aad == 1'h0 && c_in_last == 1'h0 && !c_in_valid && c_out_ready)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_KEY0, m_rd && m_map && m_idx == 6)
