  `FC(rd_IN1, m_rd && m_map && m_idx == 23)
  `FC(wr_IN1, m_wr && m_map && m_idx == 23)
  `FC(rd_IN2, m_rd && m_map && m_idx == 24)
  `FC(wr_IN2, m_wr && m_map && m_idx == 24)
  `FC(rd_IN3, m_rd && m_map && m_idx == 25)
  `FC(wr_IN3, m_wr && m_map && m_idx == 25)
  `FC(rd_IN4, m_rd && m_map && m_idx == 26)
  `FC(wr_IN4, m_wr && m_map && m_idx == 26)
  `FC(rd_OUT0, m_rd && m_map && m_idx == 27)
  `FC(wr_OUT0, m_wr && m_map && m_idx == 27)
  `FC(rd_OUT1, m_rd && m_map && m_idx == 28)
  `FC(wr_OUT1, m_wr && m_map && m_idx == 28)
  `FC(rd_OUT2, m_rd && m_map && m_idx == 29)
